class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        marks = [(-1, 'L')] + [(i, c) for i, c in enumerate(dominoes) if c != '.'] + [(len(dominoes), 'R')]
        ans = list(dominoes)
        for p in range(len(marks) - 1):
            i, a = marks[p]
            j, b = marks[p + 1]
            if a == b:
                for k in range(i + 1, j):
                    ans[k] = a
            elif a == 'R' and b == 'L':
                l, r = i + 1, j - 1
                while l < r:
                    ans[l] = 'R'; ans[r] = 'L'; l += 1; r -= 1
        return ''.join(ans)

